MonarchDownloadReportButton(
    onDownload = { format ->
        if (format.id == "email") {
            MonarchDownloadReportResult.Queued()
        } else {
            MonarchDownloadReportResult.Downloaded
        }
    },
    formats = listOf(
        MonarchDownloadReportFormat.Csv,
        MonarchDownloadReportFormat("PDF", "pdf", description = "For printing", mimeType = "application/pdf"),
        MonarchDownloadReportFormat("By email", "email", description = "Sent when it is ready"),
    ),
    variant = MonarchButtonVariant.Primary,
)
